package com.ecole.gestion_scolaire.hr.entity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; @Entity @Table(name="employment_contract") public class EmploymentContract { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @Column(name="contract_number",length=80) private String contractNumber; @Column(name="contract_type",nullable=false,length=40) private String contractType; @Column(name="start_date",nullable=false) private LocalDate startDate; @Column(name="end_date") private LocalDate endDate; @Column(name="position_title",length=150) private String positionTitle; @Column(name="workload_type",length=30) private String workloadType; @Column(name="weekly_hours",precision=6,scale=2) private BigDecimal weeklyHours; @Column(nullable=false,length=30) private String status; @Column(columnDefinition="TEXT") private String notes; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; @PrePersist void pre(){var n=OffsetDateTime.now();createdAt=n;updatedAt=n;} @PreUpdate void upd(){updatedAt=OffsetDateTime.now();} public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getContractNumber(){return contractNumber;} public void setContractNumber(String v){contractNumber=v;} public String getContractType(){return contractType;} public void setContractType(String v){contractType=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public String getPositionTitle(){return positionTitle;} public void setPositionTitle(String v){positionTitle=v;} public String getWorkloadType(){return workloadType;} public void setWorkloadType(String v){workloadType=v;} public BigDecimal getWeeklyHours(){return weeklyHours;} public void setWeeklyHours(BigDecimal v){weeklyHours=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} }